CREATE TABLE IF NOT EXISTS pos_peripheriques (id INTEGER PRIMARY KEY AUTOINCREMENT,point_vente_id INTEGER NOT NULL REFERENCES pos_points_vente(id),type TEXT NOT NULL CHECK(type IN ('imprimante_ticket','tiroir_caisse','terminal_paiement','scanner')),nom TEXT NOT NULL,connexion TEXT NOT NULL DEFAULT 'usb' CHECK(connexion IN ('usb','reseau','serie')),adresse TEXT,statut TEXT NOT NULL DEFAULT 'inactif' CHECK(statut IN ('inactif','actif','erreur')),last_seen_at TEXT,created_at TEXT NOT NULL DEFAULT(datetime('now')),UNIQUE(point_vente_id,type,nom));
CREATE TABLE IF NOT EXISTS pos_kds_commandes (id INTEGER PRIMARY KEY AUTOINCREMENT,ticket_id INTEGER NOT NULL UNIQUE REFERENCES pos_tickets(id),point_vente_id INTEGER NOT NULL REFERENCES pos_points_vente(id),numero TEXT NOT NULL,statut TEXT NOT NULL DEFAULT 'a_preparer' CHECK(statut IN ('a_preparer','en_preparation','prete','servie','annulee')),priorite INTEGER NOT NULL DEFAULT 0,envoyee_at TEXT NOT NULL DEFAULT(datetime('now')),commencee_at TEXT,prete_at TEXT,servie_at TEXT,updated_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE INDEX IF NOT EXISTS idx_kds_file ON pos_kds_commandes(point_vente_id,statut,priorite DESC,envoyee_at);
CREATE TABLE IF NOT EXISTS stock_lots (id INTEGER PRIMARY KEY AUTOINCREMENT,uuid TEXT NOT NULL UNIQUE,hotel_id INTEGER NOT NULL REFERENCES hotels(id),produit_id INTEGER NOT NULL REFERENCES stock_produits(id),numero_lot TEXT NOT NULL,date_reception TEXT NOT NULL,date_expiration TEXT,quantite_initiale REAL NOT NULL CHECK(quantite_initiale>0),quantite_restante REAL NOT NULL CHECK(quantite_restante>=0),prix_unitaire REAL NOT NULL DEFAULT 0,fournisseur_id INTEGER REFERENCES fournisseurs(id),bon_commande_id INTEGER REFERENCES bons_commande(id),statut TEXT NOT NULL DEFAULT 'disponible' CHECK(statut IN ('disponible','epuise','bloque','expire')),created_at TEXT NOT NULL DEFAULT(datetime('now')),updated_at TEXT NOT NULL DEFAULT(datetime('now')),UNIQUE(hotel_id,produit_id,numero_lot));
CREATE INDEX IF NOT EXISTS idx_stock_lots_fefo ON stock_lots(hotel_id,produit_id,statut,date_expiration);
CREATE TABLE IF NOT EXISTS stock_inventaires (id INTEGER PRIMARY KEY AUTOINCREMENT,uuid TEXT NOT NULL UNIQUE,hotel_id INTEGER NOT NULL REFERENCES hotels(id),reference TEXT NOT NULL UNIQUE,date_inventaire TEXT NOT NULL,statut TEXT NOT NULL DEFAULT 'brouillon' CHECK(statut IN ('brouillon','en_comptage','cloture')),notes TEXT,created_by INTEGER REFERENCES users(id),closed_by INTEGER REFERENCES users(id),created_at TEXT NOT NULL DEFAULT(datetime('now')),closed_at TEXT);
CREATE TABLE IF NOT EXISTS stock_inventaire_lignes (inventaire_id INTEGER NOT NULL REFERENCES stock_inventaires(id) ON DELETE CASCADE,produit_id INTEGER NOT NULL REFERENCES stock_produits(id),quantite_theorique REAL NOT NULL,quantite_comptee REAL,ecart REAL,commentaire TEXT,PRIMARY KEY(inventaire_id,produit_id));
